  // Safety
  'Part of Windows or security software. Ending it could make the system unstable or unprotected.': ['Forma parte de Windows o de software de seguridad. Finalizarlo podría dejar el sistema inestable o desprotegido.', '属于 Windows 或安全软件。结束它可能使系统不稳定或失去保护。', 'Teil von Windows oder Sicherheitssoftware. Beenden könnte das System instabil oder ungeschützt machen.'],
  'Runs as a system service (session 0). The optimizer never ends services.': ['Se ejecuta como servicio del sistema (sesión 0). El optimizador nunca finaliza servicios.', '作为系统服务运行（会话 0）。优化器从不结束服务。', 'Läuft als Systemdienst (Sitzung 0). Der Optimierer beendet nie Dienste.'],
  'Ending closes the program; unsaved data is lost.': ['Finalizarlo cierra el programa; se pierden los datos sin guardar.', '结束会关闭该程序；未保存的数据会丢失。', 'Beenden schließt das Programm; ungespeicherte Daten gehen verloren.'],
  'System- or security-relevant entry. It is never disabled.': ['Entrada relevante para el sistema o la seguridad. Nunca se desactiva.', '与系统或安全相关的条目，永远不会被禁用。', 'System- oder sicherheitsrelevanter Eintrag. Er wird nie deaktiviert.'],
  'Probably a driver or hardware helper; device features could be missing.': ['Probablemente un ayudante de controlador o hardware; podrían faltar funciones del dispositivo.', '可能是驱动或硬件辅助程序；设备功能可能会缺失。', 'Vermutlich ein Treiber- oder Hardware-Helfer; Gerätefunktionen könnten fehlen.'],
  'The program no longer starts automatically afterwards.': ['Después, el programa ya no se inicia automáticamente.', '之后该程序将不再自动启动。', 'Das Programm startet danach nicht mehr automatisch.'],

  // Service and validation messages
  'Simulation complete – no system changes were made.': ['Simulación completada: no se hicieron cambios en el sistema.', '模拟完成——未对系统做任何更改。', 'Simulation abgeschlossen – es wurden keine Systemänderungen vorgenommen.'],
  'The data has changed since the scan. Please scan again.': ['Los datos han cambiado desde el análisis. Vuelve a analizar.', '自扫描以来数据已更改。请重新扫描。', 'Die Daten haben sich seit dem Scan geändert. Bitte scanne erneut.'],
  'Unknown scan type.': ['Tipo de análisis desconocido.', '未知的扫描类型。', 'Unbekannte Scan-Art.'],
  'A scan is already running.': ['Ya hay un análisis en curso.', '已有扫描正在运行。', 'Ein Scan läuft bereits.'],
  'The scan failed.': ['El análisis falló.', '扫描失败。', 'Der Scan ist fehlgeschlagen.'],
  'Invalid scan id.': ['Id de análisis no válido.', '无效的扫描 ID。', 'Ungültige Scan-ID.'],
  'This scan no longer exists. Please scan again.': ['Este análisis ya no existe. Vuelve a analizar.', '此扫描已不存在。请重新扫描。', 'Diesen Scan gibt es nicht mehr. Bitte scanne erneut.'],
  'The selection contains invalid ids.': ['La selección contiene ids no válidos.', '所选内容包含无效 ID。', 'Die Auswahl enthält ungültige IDs.'],
  'The selection contains unknown actions.': ['La selección contiene acciones desconocidas.', '所选内容包含未知操作。', 'Die Auswahl enthält unbekannte Aktionen.'],
  'Blocked actions cannot be selected.': ['Las acciones bloqueadas no se pueden seleccionar.', '已阻止的操作无法选择。', 'Gesperrte Aktionen können nicht ausgewählt werden.'],
  'This preview does not exist (any more). Please scan again.': ['Esta vista previa no existe (ya). Vuelve a analizar.', '此预览不存在（或已失效）。请重新扫描。', 'Diese Vorschau gibt es (nicht mehr). Bitte scanne erneut.'],
  'The preview must be validated successfully before confirming.': ['La vista previa debe validarse correctamente antes de confirmar.', '确认前必须成功验证预览。', 'Die Vorschau muss vor dem Bestätigen erfolgreich geprüft werden.'],
  'The validation is too old. Please validate the preview again.': ['La validación es demasiado antigua. Vuelve a validar la vista previa.', '验证已过期。请重新验证预览。', 'Die Prüfung ist zu alt. Bitte prüfe die Vorschau erneut.'],
  'The optimization must be confirmed explicitly first.': ['Primero hay que confirmar la optimización de forma explícita.', '必须先明确确认优化。', 'Die Optimierung muss zuerst ausdrücklich bestätigt werden.'],
  'The preview is no longer valid.': ['La vista previa ya no es válida.', '预览已不再有效。', 'Die Vorschau ist nicht mehr gültig.'],
  'Invalid preview id.': ['Id de vista previa no válido.', '无效的预览 ID。', 'Ungültige Vorschau-ID.'],
  'The preview has expired. Please scan again so the values match the current state.': ['La vista previa ha caducado. Vuelve a analizar para que los valores coincidan con el estado actual.', '预览已过期。请重新扫描，使数值与当前状态一致。', 'Die Vorschau ist abgelaufen. Bitte scanne erneut, damit die Werte zum aktuellen Stand passen.'],
  'No action is selected.': ['No hay ninguna acción seleccionada.', '未选择任何操作。', 'Keine Aktion ausgewählt.'],
  '{count} unknown action(s) in the selection.': ['{count} acción(es) desconocida(s) en la selección.', '所选内容中有 {count} 个未知操作。', '{count} unbekannte Aktion(en) in der Auswahl.'],
  'Blocked actions must not be selected.': ['No se deben seleccionar acciones bloqueadas.', '不得选择已阻止的操作。', 'Gesperrte Aktionen dürfen nicht ausgewählt sein.'],
  'This action can no longer be carried out.': ['Esta acción ya no se puede realizar.', '此操作已无法执行。', 'Diese Aktion kann nicht mehr ausgeführt werden.'],
  'The current state could not be checked. Please scan again.': ['No se pudo comprobar el estado actual. Vuelve a analizar.', '无法检查当前状态。请重新扫描。', 'Der aktuelle Stand konnte nicht geprüft werden. Bitte scanne erneut.'],
  'The current state of this action could not be checked.': ['No se pudo comprobar el estado actual de esta acción.', '无法检查此操作的当前状态。', 'Der aktuelle Stand dieser Aktion konnte nicht geprüft werden.'],
  '"{title}" no longer matches the current state of the PC.': ['"{title}" ya no coincide con el estado actual del PC.', '“{title}”与电脑的当前状态不再一致。', '"{title}" passt nicht mehr zum aktuellen Stand des PCs.'],
  'Would need administrator rights later. None are requested in this phase.': ['Necesitaría permisos de administrador más adelante. En esta fase no se pide ninguno.', '之后需要管理员权限。此阶段不会请求。', 'Bräuchte später Administratorrechte. In dieser Phase wird nichts angefordert.'],
  'An action with increased risk is selected.': ['Hay seleccionada una acción con riesgo elevado.', '已选择一项风险较高的操作。', 'Eine Aktion mit erhöhtem Risiko ist ausgewählt.'],
  'The scan was incomplete; some areas could not be read.': ['El análisis fue incompleto; no se pudieron leer algunas áreas.', '扫描不完整；某些区域无法读取。', 'Der Scan war unvollständig; einige Bereiche konnten nicht gelesen werden.'],
  'All values are estimates. No freed space is guaranteed.': ['Todos los valores son estimaciones. No se garantiza ningún espacio liberado.', '所有数值均为估算，不保证释放空间。', 'Alle Werte sind Schätzungen. Frei werdender Platz ist nicht garantiert.'],
  'Unknown error': ['Error desconocido', '未知错误', 'Unbekannter Fehler'],
